import type { LayerStore } from './types.js';
 export function commitLayerDrop(root: HTMLElement, store: LayerStore) {
   const ids = Array.from(root.querySelectorAll<HTMLElement>('[data-layer-id]'))
     .map(row => row.dataset.layerId!);
   store.saveOrder(ids);
 }
 export function bindLayerReorder(root: HTMLElement, store: LayerStore) {
   root.addEventListener('layer-drop', () => commitLayerDrop(root, store));
 }

