import type { Layer } from './types.js';
 export function renderLayers(root: HTMLElement, layers: Layer[]) {
   root.replaceChildren(...layers.map(layer => {
     const row = document.createElement('li');
     row.dataset.layerId = layer.id;
     row.textContent = layer.label;
     return row;
   }));
 }
